export function applyEnemyHit(ship) {
  // TODO: lives were added to the design, but this handler predates them.
  return { ...ship, destroyed: true };
}

import { applyEnemyHit } from './damage.js';

export function resolveEnemyShot(ship, shot) {
  if (!overlaps(ship, shot)) return ship;
  return applyEnemyHit(ship);
}

function overlaps(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.hypot(dx, dy) <= a.radius + b.radius;
}

const INVULN_TICKS = 90;

export function applyEnemyHit(ship) {
  if (ship.invulnerableTicks > 0) return ship;
  const lives = ship.lives - 1;
  return {
    ...ship,
    lives,
    destroyed: lives <= 0,
    invulnerableTicks: lives > 0 ? INVULN_TICKS : 0,
  };
}

