import test from 'node:test';
import assert from 'node:assert/strict';
import { applyEnemyHit } from '../src/damage.js';

test('one hit costs exactly one life', () => {
  const ship = applyEnemyHit({ lives: 3, invulnerableTicks: 0 });
  assert.equal(ship.lives, 2);
  assert.equal(ship.destroyed, false);
  assert.equal(ship.invulnerableTicks, 90);
});

test('the third hit destroys the ship', () => {
  const ship = applyEnemyHit({ lives: 1, invulnerableTicks: 0 });
  assert.equal(ship.lives, 0);
  assert.equal(ship.destroyed, true);
});

test('an invulnerable ship shrugs the hit off', () => {
  const ship = applyEnemyHit({ lives: 2, invulnerableTicks: 45 });
  assert.equal(ship.lives, 2);
});

