const BAND = { top: 300, bottom: 380 };

export function applyVerticalInput(ship, input, enabled) {
  if (!enabled) return ship;
  let y = ship.y;
  if (input.up) y -= ship.speedY;
  if (input.down) y += ship.speedY;
  return { ...ship, y: Math.min(BAND.bottom, Math.max(BAND.top, y)) };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { applyVerticalInput } from '../src/movement.js';

const ship = { y: 340, speedY: 2 };

test('vertical input is ignored while the feature is off', () => {
  assert.equal(applyVerticalInput(ship, { up: true }, false).y, 340);
});

test('upward travel clamps at the top of the play band', () => {
  const high = { ...ship, y: 301 };
  assert.equal(applyVerticalInput(high, { up: true }, true).y, 300);
});

test('downward travel clamps at the bottom of the play band', () => {
  const low = { ...ship, y: 379 };
  assert.equal(applyVerticalInput(low, { down: true }, true).y, 380);
});
